parameters.jsCode:
// NODE: Config   (Code node, run once)
return [{ json: {
  testMode: $execution.mode === 'test',   // manual runs never log or email
  dailyCap: 2,                            // 2 pins daily (11 AM & 5 PM EST)
  recentKeywordWindow: 60,
  recentStyleWindow: 8,
  brand: 'Finmatrix',
  author: 'Finmatrix',
  siteUrl: 'https://finmatrix.cloud',
  disclaimer: 'Educational estimates only. Not financial advice.',
  blocklist: ['myusfinance','nerdwallet','bankrate','smartasset','money moves','moneymoves','calculatorskit','investopedia','dave ramsey'],
  cfAccountId: 'PASTE_CLOUDFLARE_ACCOUNT_ID',
  cloudflareModel: '@cf/black-forest-labs/flux-1-schnell',
  vpsRenderUrl: 'http://31.97.232.154:3000/render',   // switch to https://pins.finmatrix.cloud/render after nginx
  // Dated facts. Strategist may only use these tokens when factsVerified is true.
  // VERIFY at irs.gov before enabling; values below are UNVERIFIED placeholders.
  factsVerified: false,
  facts: { iraLimit: 7500, k401Limit: 24500, rmdAge: '73 or 75, depending on birth year' }
}}];

const items = $input.all();
const boards = items.map(item => item.json).filter(b => b.BoardID && b.IsActive !== false && b.IsActive !== 'FALSE');
return [{ json: { boards, count: boards.length } }];

// NODE: Style Picker (Intelligent Multi-Pillar Router & Anti-Repetition Engine)
const prev = $json;
const kw = (prev.targetKeyword || '').toLowerCase();
const pil = (prev.pillar || '').toLowerCase();

// 1. Fetch recent queue history from Google Sheets (last 10 runs)
let hist = [];
try {
  hist = $('Fetch Recent Queue History from Google Sheets').all().map(i => i.json);
} catch (e) {}

const recentLayouts = hist.slice(-8).map(r => r.LayoutVariant || r.PinStyle || r.StyleName).filter(Boolean);
const recentPalettes = hist.slice(-6).map(r => (r.PaletteId || r.ColorTheme || '').toLowerCase()).filter(Boolean);

// 2. Comprehensive Pillar & Topic Mapping
let candidates = [];

// A. Comparison Duel (vs, compare, comparison, difference, or)
if (/(?:^|\W)(vs\.?|versus|compare|comparison|difference|or)(?:\W|$)/i.test(kw)) {
  candidates = ['LAYOUT_COMPARE_DUEL', 'LAYOUT_METRIC_MATRIX'];
}
// B. Retirement, 401(k), Roth, IRA, Pension, Nest Egg, Investing, Return
else if (/(?:^|\W)(401k|401\(k\)|ira|roth|retire|retirement|pension|nest egg|rate of return|invest|investing|stock|wealth|compound)(?:\W|$)/i.test(kw) || pil.includes('retire')) {
  candidates = ['LAYOUT_TIMELINE_PATH', 'LAYOUT_COMPARE_DUEL', 'LAYOUT_METRIC_MATRIX', 'LAYOUT_PILLAR_RULES'];
}
// C. Credit Rights, Disputes, Credit Cards, Credit Scores, Bureau, FCRA
else if (/(?:^|\W)(dispute|rights|score|credit score|bureau|fraud|chargeback|statement|fcra|transunion|equifax|experian|consumer)(?:\W|$)/i.test(kw)) {
  candidates = ['LAYOUT_PILLAR_RULES', 'LAYOUT_TIMELINE_PATH', 'LAYOUT_METRIC_MATRIX'];
}
// D. Debt Elimination, Payoff, Snowball, Avalanche
else if (/(?:^|\W)(debt|payoff|snowball|avalanche|consolidation|balances?|credit card debt|debt-free)(?:\W|$)/i.test(kw) || pil.includes('debt')) {
  candidates = ['LAYOUT_DEBT_DONUT', 'LAYOUT_TIMELINE_PATH', 'LAYOUT_COMPARE_DUEL'];
}
// E. Budgeting, Cash Flow, Savings, Emergency Fund, 50/30/20
else if (/(?:^|\W)(budget|budgeting|50\/30\/20|expense|expenses|spending|spend|cash flow|emergency fund|hysa|savings?|save money)(?:\W|$)/i.test(kw) || pil.includes('saving') || pil.includes('budget')) {
  candidates = ['LAYOUT_BUDGET_PIE', 'LAYOUT_PILLAR_RULES', 'LAYOUT_METRIC_MATRIX'];
}
// F. Loans, Mortgages, EMI, Car Loans, Amortization (ONLY real loans use LOAN_STUDIO!)
else if (/(?:^|\W)(loan|loans|mortgage|emi|car loan|auto loan|borrow|apr|interest rate|refinance|amortization)(?:\W|$)/i.test(kw) || pil.includes('loan') || pil.includes('mortgage')) {
  candidates = ['LAYOUT_LOAN_STUDIO', 'LAYOUT_COMPARE_DUEL'];
}
// G. Default / General Fallback across all other 6 rich layouts (NEVER default to Loan Studio for non-loans!)
else {
  candidates = ['LAYOUT_TIMELINE_PATH', 'LAYOUT_COMPARE_DUEL', 'LAYOUT_PILLAR_RULES', 'LAYOUT_METRIC_MATRIX', 'LAYOUT_BUDGET_PIE', 'LAYOUT_DEBT_DONUT'];
}

// 3. Strict Anti-Repetition Guard: Never repeat the last used layout!
const lastUsed = recentLayouts.length ? recentLayouts[recentLayouts.length - 1] : null;
let filteredCandidates = candidates.filter(l => l !== lastUsed);
if (!filteredCandidates.length) filteredCandidates = candidates;
const selectedLayout = filteredCandidates[Math.floor(Math.random() * filteredCandidates.length)];

// 4. Curated 10 Luxury Color Palettes (with Anti-Repetition)
const ALL_PALETTES = ['sapphire', 'emerald', 'amber', 'violet', 'cyan', 'coral', 'slate', 'champagne', 'obsidian_teal', 'obsidian_gold'];
const lastPalette = recentPalettes.length ? recentPalettes[recentPalettes.length - 1] : null;
let freshPalettes = ALL_PALETTES.filter(p => p !== lastPalette);
if (!freshPalettes.length) freshPalettes = ALL_PALETTES;
const selectedColorTheme = freshPalettes[Math.floor(Math.random() * freshPalettes.length)];

// 5. Randomize Headline Geometries & Textures
const SHAPES = ['CLEAN_MINIMAL', 'PILL_BADGE', 'OFFSET_BOX', 'SLANTED_RIBBON', 'GLASS_CONSOLE'];
const PATTERNS = ['DOT_MATRIX', 'FINANCIAL_GRID', 'AMBIENT_ORBS', 'CLEAN_GRADIENT'];
const selectedShape = SHAPES[Math.floor(Math.random() * SHAPES.length)];
const selectedPattern = PATTERNS[Math.floor(Math.random() * PATTERNS.length)];

return [{
  json: {
    ...prev,
    layoutVariant: selectedLayout,
    intentType: selectedLayout,
    colorTheme: selectedColorTheme,
    paletteKey: selectedColorTheme.toUpperCase(),
    headlineShape: selectedShape,
    bgPattern: selectedPattern,
    theme: selectedColorTheme.startsWith('obsidian') ? 'DARK_LUXE' : 'LIGHT_CORP'
  }
}];

// NODE: Build Strategist Request
const d = $json; const cfg = $('Config').first().json;

const TOKENS = [
  cfg.factsVerified ? 'ALWAYS: {iraLimit} {k401Limit} {rmdAge}' : 'Do NOT state any tax limit, IRS threshold or age rule.',
  'scenarioType LOAN: {loanAmount} {ratePct} {years} {payment} {totalPaid} {totalInterest} {extraMonthly} {interestSaved} {yearsSaved}',
  'scenarioType COMPOUND: {startBalance} {monthlyContribution} {ratePct} {years} {futureValue} {totalContributions} {interestEarned}',
  'scenarioType BUDGET: {monthlyIncome} {needs} {wants} {savings}',
  'scenarioType EMERGENCY: {monthlyExpenses} {target3} {target6} {monthlySave} {monthsToGoal}',
  'scenarioType DEBT: {debtBalance} {ratePct} {debtPayment} {monthsToPayoff} {totalInterest}'
].join('\n');

let schemaGuide = '';
if (d.layoutVariant === 'CALC_HERO_ART') {
  schemaGuide = JSON.stringify({
    scriptTag: 'Short 2-4 word theme label',
    headline: '3-5 PUNCHY WORDS IN ALL CAPS',
    subtitle: 'Clear benefit explaining what to calculate under 10 words',
    toolName: 'Finmatrix Calculator Tool Name',
    scenarioType: 'LOAN',
    scenario: { loanAmount: 350000, ratePct: 6.5, years: 30, extraMonthly: 200 },
    blocks: [],
    checks: ['Point 1 under 10 words', 'Point 2 under 10 words', 'Point 3 under 10 words', 'Point 4 under 10 words'],
    takeaway: 'Actionable takeaway under 18 words',
    cta: 'Calculate Now',
    pinTitle: 'Compelling Title Case Pin Title with Target Query Under 90 Chars',
    pinDescription: 'Engaging plain text description between 250 and 380 characters that answers the query. No URLs, no hashtags, max 2 emojis.',
    altText: 'Descriptive alt text under 100 characters',
    hashtags: ['#Tag1', '#Tag2', '#Tag3', '#Tag4', '#Tag5'],
    taggedTopics: ['Topic 1', 'Topic 2', 'Topic 3', 'Topic 4', 'Topic 5']
  }, null, 2);
} else if (d.layoutVariant === 'COMPARE_MATRIX') {
  schemaGuide = JSON.stringify({
    scriptTag: 'Short 2-4 word theme label',
    headline: 'OPTION A VS OPTION B',
    subtitle: 'Subtitle comparing both options under 10 words',
    scenarioType: 'NONE',
    sideA: { title: 'Option A Title', tag: 'SHORT TAG A' },
    sideB: { title: 'Option B Title', tag: 'SHORT TAG B' },
    rows: [
      { label: 'Comparison Row 1', a: 'Option A value', b: 'Option B value', icon: 'target' },
      { label: 'Comparison Row 2', a: 'Option A value', b: 'Option B value', icon: 'trending-up' },
      { label: 'Comparison Row 3', a: 'Option A value', b: 'Option B value', icon: 'piggy-bank' },
      { label: 'Comparison Row 4', a: 'Option A value', b: 'Option B value', icon: 'zap' },
      { label: 'Comparison Row 5', a: 'Option A value', b: 'Option B value', icon: 'shield-check' },
      { label: 'Comparison Row 6', a: 'Option A value', b: 'Option B value', icon: 'lightbulb' },
      { label: 'Comparison Row 7', a: 'Option A value', b: 'Option B value', icon: 'wallet' }
    ],
    blocks: [],
    takeaway: 'Actionable takeaway under 18 words',
    cta: 'Compare Options',
    pinTitle: 'Compelling Title Case Pin Title with Target Query Under 90 Chars',
    pinDescription: 'Engaging plain text description between 250 and 380 characters that answers the query. No URLs, no hashtags, max 2 emojis.',
    altText: 'Descriptive alt text under 100 characters',
    hashtags: ['#Tag1', '#Tag2', '#Tag3', '#Tag4', '#Tag5'],
    taggedTopics: ['Topic 1', 'Topic 2', 'Topic 3', 'Topic 4', 'Topic 5']
  }, null, 2);
} else if (d.layoutVariant === 'ROADMAP_TIMELINE') {
  schemaGuide = JSON.stringify({
    scriptTag: 'Short 2-4 word theme label',
    headline: '3-5 WORD ROADMAP HEADLINE',
    subtitle: 'Subtitle explaining journey under 10 words',
    scenarioType: 'NONE',
    blocks: [
      { title: 'Phase 1 Title', badge: 'Phase 01', body: 'Summary under 12 words', icon: 'shield-check', actions: ['action 1', 'action 2', 'action 3'] },
      { title: 'Phase 2 Title', badge: 'Phase 02', body: 'Summary under 12 words', icon: 'flame', actions: ['action 1', 'action 2', 'action 3'] },
      { title: 'Phase 3 Title', badge: 'Phase 03', body: 'Summary under 12 words', icon: 'zap', actions: ['action 1', 'action 2', 'action 3'] },
      { title: 'Phase 4 Title', badge: 'Phase 04', body: 'Summary under 12 words', icon: 'trending-up', actions: ['action 1', 'action 2', 'action 3'] }
    ],
    takeaway: 'Actionable takeaway under 18 words',
    cta: 'Get Free Roadmap',
    pinTitle: 'Compelling Title Case Pin Title with Target Query Under 90 Chars',
    pinDescription: 'Engaging plain text description between 250 and 380 characters that answers the query. No URLs, no hashtags, max 2 emojis.',
    altText: 'Descriptive alt text under 100 characters',
    hashtags: ['#Tag1', '#Tag2', '#Tag3', '#Tag4', '#Tag5'],
    taggedTopics: ['Topic 1', 'Topic 2', 'Topic 3', 'Topic 4', 'Topic 5']
  }, null, 2);
} else if (d.layoutVariant === 'RULE_CARDS') {
  schemaGuide = JSON.stringify({
    scriptTag: 'Short 2-4 word theme label',
    headline: '3-5 WORD FRAMEWORK HEADLINE',
    subtitle: 'Subtitle explaining framework under 10 words',
    scenarioType: 'BUDGET',
    scenario: { monthlyIncome: 5000 },
    blocks: [
      { title: 'Needs Card', badge: '50%', body: 'Summary under 12 words', icon: 'house', items: ['item 1', 'item 2', 'item 3', 'item 4'] },
      { title: 'Wants Card', badge: '30%', body: 'Summary under 12 words', icon: 'coffee', items: ['item 1', 'item 2', 'item 3', 'item 4'] },
      { title: 'Savings Card', badge: '20%', body: 'Summary under 12 words', icon: 'piggy-bank', items: ['item 1', 'item 2', 'item 3', 'item 4'] }
    ],
    takeaway: 'Actionable takeaway under 18 words',
    cta: 'Plan Your Budget',
    pinTitle: 'Compelling Title Case Pin Title with Target Query Under 90 Chars',
    pinDescription: 'Engaging plain text description between 250 and 380 characters that answers the query. No URLs, no hashtags, max 2 emojis.',
    altText: 'Descriptive alt text under 100 characters',
    hashtags: ['#Tag1', '#Tag2', '#Tag3', '#Tag4', '#Tag5'],
    taggedTopics: ['Topic 1', 'Topic 2', 'Topic 3', 'Topic 4', 'Topic 5']
  }, null, 2);
} else if (d.layoutVariant === 'PIE_TIPS') {
  schemaGuide = JSON.stringify({
    scriptTag: 'Short 2-4 word theme label',
    headline: '3-5 WORD ALLOCATION HEADLINE',
    subtitle: 'Subtitle explaining allocation under 10 words',
    scenarioType: 'NONE',
    blocks: [
      { title: 'Needs', badge: '50', body: 'Summary under 10 words', icon: 'house' },
      { title: 'Wants', badge: '30', body: 'Summary under 10 words', icon: 'shopping-bag' },
      { title: 'Savings', badge: '20', body: 'Summary under 10 words', icon: 'trending-up' }
    ],
    steps: [
      { title: 'Step 1 Title', body: 'Advice under 12 words', icon: 'landmark' },
      { title: 'Step 2 Title', body: 'Advice under 12 words', icon: 'zap' },
      { title: 'Step 3 Title', body: 'Advice under 12 words', icon: 'clipboard-list' },
      { title: 'Step 4 Title', body: 'Advice under 12 words', icon: 'credit-card' },
      { title: 'Step 5 Title', body: 'Advice under 12 words', icon: 'receipt' },
      { title: 'Step 6 Title', body: 'Advice under 12 words', icon: 'sprout' }
    ],
    quote: 'Memorable financial rule under 12 words',
    takeaway: 'Actionable takeaway under 18 words',
    cta: 'See Split Details',
    pinTitle: 'Compelling Title Case Pin Title with Target Query Under 90 Chars',
    pinDescription: 'Engaging plain text description between 250 and 380 characters that answers the query. No URLs, no hashtags, max 2 emojis.',
    altText: 'Descriptive alt text under 100 characters',
    hashtags: ['#Tag1', '#Tag2', '#Tag3', '#Tag4', '#Tag5'],
    taggedTopics: ['Topic 1', 'Topic 2', 'Topic 3', 'Topic 4', 'Topic 5']
  }, null, 2);
} else if (d.layoutVariant === 'TABLE_CHECK') {
  schemaGuide = JSON.stringify({
    scriptTag: 'Short 2-4 word theme label',
    headline: '3-5 WORD TABLE HEADLINE',
    subtitle: 'Subtitle explaining table under 10 words',
    scenarioType: 'NONE',
    table: {
      cols: ['Col 1 Header', 'Col 2 Header', 'Col 3 Header', 'Col 4 Header'],
      rows: [
        { c1: 'Row 1 Col 1', c2: 'Row 1 Col 2', c3: 'Row 1 Col 3', c4: 'Row 1 Col 4' },
        { c1: 'Row 2 Col 1', c2: 'Row 2 Col 2', c3: 'Row 2 Col 3', c4: 'Row 2 Col 4' },
        { c1: 'Row 3 Col 1', c2: 'Row 3 Col 2', c3: 'Row 3 Col 3', c4: 'Row 3 Col 4' },
        { c1: 'Row 4 Col 1', c2: 'Row 4 Col 2', c3: 'Row 4 Col 3', c4: 'Row 4 Col 4' }
      ]
    },
    checks: [
      'Checklist rule 1 under 12 words',
      'Checklist rule 2 under 12 words',
      'Checklist rule 3 under 12 words',
      'Checklist rule 4 under 12 words',
      'Checklist rule 5 under 12 words'
    ],
    blocks: [],
    takeaway: 'Actionable takeaway under 18 words',
    cta: 'Audit Your Rates',
    pinTitle: 'Compelling Title Case Pin Title with Target Query Under 90 Chars',
    pinDescription: 'Engaging plain text description between 250 and 380 characters that answers the query. No URLs, no hashtags, max 2 emojis.',
    altText: 'Descriptive alt text under 100 characters',
    hashtags: ['#Tag1', '#Tag2', '#Tag3', '#Tag4', '#Tag5'],
    taggedTopics: ['Topic 1', 'Topic 2', 'Topic 3', 'Topic 4', 'Topic 5']
  }, null, 2);
} else {
  // GRID_6 default
  schemaGuide = JSON.stringify({
    scriptTag: 'Short 2-4 word theme label',
    headline: '6 EXPENSIVE MONEY LEAKS',
    subtitle: 'Subtitle explaining traps under 10 words',
    scenarioType: 'NONE',
    blocks: [
      { title: 'Point 1', badge: '01', body: 'Description under 12 words', icon: 'receipt' },
      { title: 'Point 2', badge: '02', body: 'Description under 12 words', icon: 'utensils' },
      { title: 'Point 3', badge: '03', body: 'Description under 12 words', icon: 'credit-card' },
      { title: 'Point 4', badge: '04', body: 'Description under 12 words', icon: 'landmark' },
      { title: 'Point 5', badge: '05', body: 'Description under 12 words', icon: 'shopping-cart' },
      { title: 'Point 6', badge: '06', body: 'Description under 12 words', icon: 'piggy-bank' }
    ],
    takeaway: 'Actionable takeaway under 18 words',
    cta: 'Fix These Leaks',
    pinTitle: 'Compelling Title Case Pin Title with Target Query Under 90 Chars',
    pinDescription: 'Engaging plain text description between 250 and 380 characters that answers the query. No URLs, no hashtags, max 2 emojis.',
    altText: 'Descriptive alt text under 100 characters',
    hashtags: ['#Tag1', '#Tag2', '#Tag3', '#Tag4', '#Tag5'],
    taggedTopics: ['Topic 1', 'Topic 2', 'Topic 3', 'Topic 4', 'Topic 5']
  }, null, 2);
}

let prompt = 'You are the content strategist for Finmatrix (' + cfg.siteUrl + '), a US personal-finance calculator site.\n' +
  'Write the CONTENT for one Pinterest infographic pin. Layout and design are handled by code.\n\n' +
  'TARGET QUERY: "' + d.targetKeyword + '" | INTENT: ' + d.intentType + ' | LAYOUT: ' + d.layoutVariant + ' | BOARD: ' + d.targetBoard + '\n\n' +
  'HARD RULES:\n' +
  '1. The brand is only "Finmatrix". Never mention any other brand, site or product.\n' +
  '2. NEVER write a dollar amount or any computed figure yourself. When a figure is needed use ONLY these tokens, written in braces:\n' +
  TOKENS + '\n' +
  '   Percentages that belong to a named rule (50/30/20, 4% rule) and small counts (3 months, 6 steps) are allowed.\n' +
  '3. Choose realistic US scenario inputs in "scenario" for the scenarioType you pick. Mention any interest rate only as "example rate" and with the {ratePct} token.\n' +
  '4. Plain text only: no markdown, asterisks or emojis in on-image text.\n' +
  '5. Length limits: scriptTag max 4 words; headline 2-5 words; subtitle max 10 words; block title max 5 words; block body max 14 words; items/actions max 6 words; takeaway max 18 words; cta max 4 words.\n' +
  '6. Audience: US readers. Educational, specific, no hype, no guarantees.\n' +
  '7. pinTitle: max 90 characters, title case, naturally contains the target query. pinDescription: 250-380 characters, plain text, answers the query, may use tokens, NO URLs, NO hashtags, at most 2 emojis. altText: max 100 characters describing the infographic. hashtags: exactly 5 relevant hashtags. taggedTopics: exactly 5 Pinterest topics.\n\n' +
  'Return ONLY a valid JSON object matching this exact schema:\n' +
  schemaGuide + '\n\n' +
  'No markdown code fences, no commentary. Return ONLY the raw JSON object.';

if (d.errors && d.errors.length) prompt += '\n\nYOUR PREVIOUS ATTEMPT FAILED VALIDATION. FIX THESE ISSUES:\n- ' + d.errors.join('\n- ');

return [{ json: { ...d, requestBody: { contents: [{ role: 'user', parts: [{ text: prompt }] }] } } }];

// NODE: Validate & Compute
const cfg = $('Config').first().json;
const prev = { ...$('Build Strategist Request').item.json }; delete prev.requestBody;
const attempt = (prev.attempt || 0) + 1;
const errors = [];
const fail = () => [{ json: { ...prev, valid: false, errors, attempt } }];

// Detect upstream HTTP / Gemini API errors
if ($json.error || $json.status === 429 || $json.status === 503 || $json.statusCode >= 400) {
  const errMsg = $json.error?.message || $json.message || ('HTTP Status ' + ($json.status || $json.statusCode));
  errors.push('Gemini API Error: ' + errMsg);
  // Mark max attempts on quota/rate-limit so it doesn't loop and hammer the API
  return [{ json: { ...prev, valid: false, errors, attempt: 3 } }];
}

const raw = ($json.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
let c = null;
const FENCE = String.fromCharCode(96).repeat(3);   // avoids a literal fence inside this block
try { c = JSON.parse(raw.split(FENCE + 'json').join('').split(FENCE).join('').trim()); } catch (e) { errors.push('Response was empty or not valid JSON'); }
if (!c) return fail();

// ---- 1. layout requirements
const L = prev.layoutVariant, len = (x) => (Array.isArray(x) ? x.length : 0);
const need = (ok, msg) => { if (!ok) errors.push(msg); };
need(c.headline && c.headline.split(/\s+/).length <= 9, 'headline must be 2-8 words');
if (L === 'CALC_HERO_ART') { need(c.toolName, 'toolName required'); need(len(c.checks) === 4, 'checks must have exactly 4 items'); need(c.scenarioType !== 'NONE', 'scenarioType must not be NONE'); }
if (L === 'COMPARE_MATRIX') { need(c.sideA?.title && c.sideB?.title, 'sideA/sideB required'); need(len(c.rows) === 7, 'rows must have exactly 7 items'); }
if (L === 'ROADMAP_TIMELINE') { need(len(c.blocks) === 4, 'blocks must have exactly 4 phases'); (c.blocks || []).forEach((b, i) => need(len(b.actions) >= 3, 'phase ' + (i + 1) + ' needs 3 actions')); }
if (L === 'RULE_CARDS') { need(len(c.blocks) === 3, 'blocks must have exactly 3 items'); (c.blocks || []).forEach((b, i) => need(b.badge && len(b.items) >= 3, 'card ' + (i + 1) + ' needs badge and 3+ items')); }
if (L === 'PIE_TIPS') { need(len(c.blocks) === 3, 'blocks must have exactly 3 items'); const sum = (c.blocks || []).reduce((s, b) => s + (parseFloat(b.badge) || 0), 0); need(Math.abs(sum - 100) < 0.5, 'block badges must be percentages summing to 100'); need(len(c.steps) === 6, 'steps must have exactly 6 items'); }
if (L === 'GRID_6') need(len(c.blocks) === 6, 'blocks must have exactly 6 items');
if (L === 'TABLE_CHECK') { need(len(c.table?.cols) === 4, 'table.cols must have 4 items'); need(len(c.table?.rows) >= 4, 'table.rows needs 4-5 rows'); need(len(c.checks) === 5, 'checks must have exactly 5 items'); }
if (errors.length) return fail();

// ---- 2. guards on raw LLM text (numbers must come from tokens)
const strings = [];
const walk = (o) => { if (typeof o === 'string') strings.push(o); else if (Array.isArray(o)) o.forEach(walk); else if (o && typeof o === 'object') Object.entries(o).forEach(([k, v]) => { if (k !== 'scenario') walk(v); }); };
walk(c);
for (const s of strings) {
  if (/\$\s?\d/.test(s)) errors.push('Raw dollar amount in "' + s.slice(0, 50) + '": use a token instead');
  if (/\d+(\.\d+)?\s?%\s*(apy|apr|interest|return|yield)/i.test(s)) errors.push('Raw rate claim in "' + s.slice(0, 50) + '": use {ratePct} labelled as an example rate');
  if (!cfg.factsVerified && /\{(iraLimit|k401Limit|rmdAge)\}/.test(s)) errors.push('Fact tokens are not allowed (facts are unverified)');
}
if (errors.length) return fail();

// ---- 3. deterministic calculations
const fmt0 = (n) => '$' + Math.round(n).toLocaleString('en-US');
const fmt2 = (n) => '$' + n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const pmt = (P, apr, yrs) => { const r = apr / 100 / 12, n = Math.round(yrs * 12); return r === 0 ? P / n : P * r / (1 - Math.pow(1 + r, -n)); };
const payoff = (P, apr, pay) => { const r = apr / 100 / 12; let bal = P, m = 0, interest = 0; while (bal > 0.005 && m < 1200) { const i = bal * r; if (pay <= i) return null; interest += i; bal -= Math.min(pay - i, bal); m++; } return { months: m, interest }; };

const rawS = c.scenario || {};
const defaults = {
  loanAmount: 250000, ratePct: 6.5, years: 30, extraMonthly: 0,
  startBalance: 25000, monthlyContribution: 500,
  monthlyIncome: 5000,
  monthlyExpenses: 3000, monthlySave: 500,
  debtBalance: 10000, debtPayment: 300
};
const s = { ...defaults, ...rawS };
const num = (k, lo, hi) => { const v = Number(s[k]); if (!isFinite(v) || v < lo || v > hi) return defaults[k]; return v; };
const dict = { ratePct: '7%' }; let ui = null;
try {
  switch (c.scenarioType) {
    case 'LOAN': {
      const P = num('loanAmount', 5000, 2e6), r = num('ratePct', 0.5, 30), y = num('years', 1, 40), extra = Math.max(0, Number(s.extraMonthly) || 0);
      const n = Math.round(y * 12), pay = pmt(P, r, y), paid = pay * n;
      Object.assign(dict, { loanAmount: fmt0(P), ratePct: r + '%', years: String(y), payment: fmt2(pay), totalPaid: fmt0(paid), totalInterest: fmt0(paid - P), extraMonthly: fmt0(extra) });
